function petFace(stage,looks){
 const selected=petOutfitSelection(looks),frame=petHeadFrames.indexOf(selected.head)+5*(petBodyFrames.indexOf(selected.body)+(selected.eyewear?4:0));
 const [left,right,y]=petOutfitFaces[stage][frame],radius=selected.eyewear?4:3.6;
 const eyes=(smile)=>[left,right].map(x=>`<ellipse cx="${x}" cy="${y}" rx="${radius}" ry="5" fill="#fae9ce"/><path d="M${x-2.3} ${y+.3} Q${x} ${y+(smile?-3.4:1.5)} ${x+2.3} ${y+.3}" fill="none" stroke="#36304b" stroke-width="1.1" stroke-linecap="round"/>`).join('');
 return `<svg class="pet-face" viewBox="0 0 100 100" aria-hidden="true"><g class="pet-blink-eyes">${eyes(false)}</g><g class="pet-smile-eyes">${eyes(true)}</g></svg>`;
}
const petAtlasKeys=['plant','books','lamp','sofa','clock','flowers','cat','stars','desk','pillow','piggy','watering','tea','painting','basket','look-scholar','look-ribbon','look-music','look-cozy','look-star','look-beret','look-bag','look-charm','food','book'];
function petProp(key,extra=''){const i=petAtlasKeys.indexOf(key);return `<span class="pet-prop ${extra}" style="background-position:${i%5*25}% ${[2.5,29,54,79,100][Math.floor(i/5)]}%" aria-hidden="true"></span>`;}
function petRoom(p){const roomClasses=p.equipped.filter(k=>k.startsWith('wall-')||k.startsWith('rug-')||k.startsWith('floor-')).join(' ');const looks=p.equipped.filter(k=>k.startsWith('look-'));const color=p.equipped.find(k=>k.startsWith('color-'))||'';
 const places={plant:[8,75,17],books:[87,61,24],lamp:[8,47,18],sofa:[85,83,29],clock:[88,27,13],flowers:[18,59,14],cat:[24,83,14],stars:[45,17,32],desk:[88,74,28],pillow:[72,87,16],piggy:[12,87,14],watering:[30,89,12],tea:[15,80,22],painting:[76,26,20],basket:[91,90,17]};
 return `<div class="pet-room ${roomClasses} ${p.energy<45?'pet-room-sleepy':''}" aria-label="${esc(p.name)}의 방"><div class="pet-room-wall"><div class="pet-window"><span class="pet-sun"></span><span class="pet-cloud"></span></div><div class="pet-wall-frame">HOME<br><small>작은 오늘, 든든한 내일</small></div></div><div class="pet-floor"></div><div class="pet-rug"></div>${p.equipped.filter(k=>places[k]).map(k=>{const [x,y,w]=places[k];return `<div class="pet-room-prop" style="left:${x}%;top:${y}%;width:${w}%" aria-label="${esc(p.items[k].name)}">${petProp(k)}</div>`;}).join('')}<div class="pet-room-label">${esc(p.name)}의 보금자리</div><button type="button" class="pet-character" aria-label="보금이 쓰다듬기" title="마우스로 살살 쓰다듬어 주세요">${petAvatar(p.stage,looks,color)}<span class="pet-stroke-hearts" aria-hidden="true">♥ ♡ ♥</span><span class="pet-shadow"></span></button><div class="pet-play-layer"></div></div>`;
}
const petSlotNames={head:'머리',eyewear:'얼굴',body:'몸통·손'};
function petItemGroup(item){return item.category==='character'?item.slot:item.category;}
function petItemPreview(p,key,item){if(petLookLabels[key])return `<div class="pet-look-preview">${petAvatar(p.stage,key,p.equipped.find(k=>k.startsWith('color-'))||'')}</div>`;if(petAtlasKeys.includes(key))return petProp(key,'pet-shop-prop');if(item.category==='color')return `<div class="pet-look-preview">${petAvatar(p.stage,'',key)}</div>`;return `<span class="pet-room-swatch ${key}" aria-hidden="true"></span>`;}
function petCoinGuide(p){const labels={attendance:['오늘의 출석','하루 10 코인'],game:['놀이터 게임 완료','하루 10 코인'],activity:['업무 · 청소 · 함께 식사','XP 2당 1 코인 · 하루 최대 20'],care:['보금이 돌보기','네 가지 돌봄 · 하루 최대 4']};return `<section class="panel pet-coin-guide"><h2>보금 코인 모으기</h2><div>${(p.coin_progress||[]).map(({key,earned,limit})=>{const percent=Math.round(earned/limit*100);return `<div class="pet-coin-progress ${percent===100?'is-complete':''}" role="progressbar" aria-label="${labels[key][0]}" aria-valuemin="0" aria-valuemax="${limit}" aria-valuenow="${earned}"><i style="width:${percent}%"></i><div><span>${labels[key][0]}</span><strong>${percent===100?'✓ 완료':percent+'%'} · ${earned}/${limit} 코인</strong><small>${labels[key][1]}</small></div></div>`;}).join('')}</div><p>오늘 받은 보상으로 표시해요. 코인을 사용해도 달성률은 유지됩니다.</p></section>`;}
function petMood(p){if(p.hunger<45)return '배가 조금 고파요. 같이 밥 먹을까요?';if(p.energy<45)return '잠깐 쉬면서 충전하고 싶어요.';if(p.hygiene<45)return '방을 함께 정리해 볼까요?';return ['오늘부터 우리 함께 지내요!','여기가 내 보금자리예요.','사원증을 달았어요! 같이 공부해요.','든든한 친구가 되어 줄게요.'][p.stage];}
function renderPetPage(){
 if(location.hash!=='#pet'||petInteraction)return;
 if(!petLoaded){if(!document.querySelector('#pet-app'))content.innerHTML='<h1 class="view-title">보금이 키우기</h1><section class="panel" id="pet-app">작은 보금자리를 준비하고 있어요…</section>';loadPet();return;}
 if(!petState){content.innerHTML=`<h1 class="view-title">보금이 키우기</h1><section class="panel pet-welcome" id="pet-app"><span class="pet-eyebrow">MY LITTLE HOME</span><h2>작은 집에서 시작하는<br>우리의 인턴 생활</h2><div class="pet-welcome-art">${petAvatar(0)}</div><p>밥을 챙기고, 쉬고, 함께 공부하며<br>나만의 보금이를 4단계로 키워 보세요.</p><form id="pet-adopt-form"><label>우리 친구 이름<input name="name" class="field" maxlength="12" value="보금이" required></label><fieldset class="pet-adopt-colors"><legend>보금이 색상 <small>처음 선택은 무료예요</small></legend><div>${[['','파랑','#78b2e5'],['color-mint','민트','#90cbbd'],['color-pink','분홍','#e9a2c6'],['color-lavender','라벤더','#b6a0df'],['color-sunset','살구','#ddb482']].map(([key,label,tone])=>`<label><input type="radio" name="color" value="${key}" ${!key?'checked':''}><span style="--pet-swatch:${tone}"></span><small>${label}</small></label>`).join('')}</div></fieldset><button type="submit" class="primary">보금이 맞이하기</button><p class="pet-notice" role="status"></p></form><small>내 계정에 저장되는 인턴 홈페이지 오리지널 캐릭터</small></section>`;return;}
 const p=petState,next=p.next_growth,previous=p.stages[p.stage].growth,progress=next?Math.min(100,(p.growth-previous)/(next-previous)*100):100;
 content.innerHTML=`<div class="pet-page" id="pet-app"><div class="pet-page-heading"><div><span class="pet-eyebrow">MY LITTLE HOME</span><h1 class="view-title">보금이 키우기</h1><p>함께 자라는 우리만의 작은 보금자리</p></div><span class="pet-coins">✦ 보금 코인 <strong>${p.coins}</strong></span></div><div class="pet-layout"><section class="pet-main"><div class="pet-name-row"><div><h2>${esc(p.name)} <span>${p.stage+1}단계 · ${esc(p.stage_name)}</span></h2><p>${esc(window.hfAuth.user.name)} 인턴의 친구</p></div><button type="button" class="pet-name-edit">이름 변경</button></div>${petRoom(p)}<p class="pet-touch-hint">보금이를 클릭하거나 마우스로 살살 쓰다듬어 주세요 ♡</p><p class="pet-speech">${esc(petMessage||petMood(p))}</p><div class="pet-actions">${Object.entries(petActionNames).map(([key,[icon,title,desc]])=>`<button type="button" data-pet-care="${key}" ${petBusy?'disabled':''}><span aria-hidden="true">${icon}</span><strong>${title}</strong><small>${p.rewarded.includes(key)?'오늘 보상 받음':'성장 +8 · 코인 +1'}</small></button>`).join('')}</div><p class="pet-notice" id="pet-action-status" role="status">${petBusy?'보금이를 돌보고 있어요…':''}</p></section><aside class="pet-side"><section class="panel pet-status-panel"><h2>오늘의 컨디션</h2>${[['hunger','포만감'],['happy','행복'],['energy','기운'],['hygiene','청결']].map(([key,label])=>`<div class="pet-stat"><div><span>${label}</span><strong>${Math.round(p[key])}</strong></div><progress max="100" value="${Math.round(p[key])}" aria-label="${label}"></progress></div>`).join('')}<p>조금씩 돌봐 주세요.<br>바쁜 날에도 보금이는 기다려 줘요.</p></section><section class="panel pet-growth"><h2>우리의 성장</h2><p class="pet-growth-period">인턴 기간 · 2027.02.26까지<br>매일 2~4가지 돌봄 · 약 12~24일 성장</p><div class="pet-growth-caption"><span>${next?'다음 단계까지 '+(next-p.growth)+' 성장':'최종 단계에 도착했어요!'}</span><strong>${p.growth} 성장</strong></div><progress max="100" value="${progress}" aria-label="성장 진행률"></progress><ol>${p.stages.map((stage,i)=>`<li class="${i<=p.stage?'unlocked':'locked'}">${petSprite(i)}<span><small>${i+1}단계 · ${stage.growth} 성장</small>${esc(stage.name)}</span>${i===p.stage?'<em>지금</em>':''}</li>`).join('')}</ol></section></aside></div>${petCoinGuide(p)}<section class="panel pet-decor"><div class="pet-store-heading"><div><h2>보금 상점</h2><p>마음에 드는 모습과 소품을 모아 나만의 방을 만들어 보세요.</p></div><small>구매한 아이템은 언제든 무료로 바꿀 수 있어요.</small></div><div class="pet-shop-tabs" role="tablist" aria-label="상점 분류">${[['character','캐릭터'],['color','색상'],['furniture','가구 · 소품'],['room','방 분위기']].map(([key,label])=>`<button role="tab" type="button" data-pet-category="${key}" aria-selected="${petShopCategory===key}">${label}</button>`).join('')}</div>${petShopCategory==='character'?`<div class="pet-slot-tabs" role="group" aria-label="착용 부위">${[['all','전체'],...Object.entries(petSlotNames)].map(([key,label])=>`<button type="button" data-pet-slot="${key}" aria-pressed="${petWearCategory===key}">${label}</button>`).join('')}</div><p class="pet-slot-note">머리(모자·헤드셋·리본·별 핀), 얼굴(안경), 몸통·손(목도리·가방·열쇠고리)에서 하나씩 선택해요. 서로 다른 부위는 함께 착용할 수 있어요.</p>`:''}<div class="pet-shop">${Object.entries(p.items).filter(([key,item])=>item.category===petShopCategory&&(petShopCategory!=='character'||petWearCategory==='all'||item.slot===petWearCategory)).map(([key,item])=>`<button type="button" data-pet-item="${key}" data-pet-item-action="buy" ${petBusy||p.owned.includes(key)||(!p.admin_shop&&p.coins<item.price)?'disabled':''}>${petItemPreview(p,key,item)}<strong>${esc(item.name)}</strong>${item.description?`<span class="pet-item-description">${esc(item.description)}</span>`:''}<small>${p.owned.includes(key)?'소장 중':p.admin_shop?'관리자 · 무료 소장':item.price+' 코인 · 구매'}</small></button>`).join('')}</div></section><section class="panel pet-inventory"><div class="pet-store-heading"><div><h2>내 소장함</h2><p>부위별로 하나씩, 최대 3개를 함께 착용해요. 교체한 소품도 계속 소장하며 장착·해제는 무료예요.</p></div>${p.admin_shop?'<small>관리자는 모든 아이템을 무료로 이용할 수 있어요.</small>':''}</div><label class="pet-inventory-filter">소장품 분류<select class="field" id="pet-inventory-category">${[['all','전체'],...Object.entries(petSlotNames),['color','색상'],['furniture','가구 · 소품'],['room','방 분위기']].map(([key,label])=>`<option value="${key}" ${petInventoryCategory===key?'selected':''}>${label}</option>`).join('')}</select></label><div class="pet-inventory-grid">${Object.entries(p.items).filter(([key,item])=>(p.admin_shop||p.owned.includes(key))&&(petInventoryCategory==='all'||petItemGroup(item)===petInventoryCategory)).map(([key,item])=>`<article class="pet-inventory-item ${p.equipped.includes(key)?'is-equipped':''}">${petItemPreview(p,key,item)}<strong>${esc(item.name)}</strong><span>${p.equipped.includes(key)?'장착 중':p.owned.includes(key)?'소장 중':'관리자 이용 가능'}</span><button type="button" class="${p.equipped.includes(key)?'pet-unequip':'pet-equip'}" data-pet-item="${key}" data-pet-item-action="${p.equipped.includes(key)&&key!=='color-blue'?'unequip':'equip'}" ${petBusy||(key==='color-blue'&&p.equipped.includes(key))?'disabled':''}>${key==='color-blue'?(p.equipped.includes(key)?'기본색 사용 중':'기본 파랑으로'):p.equipped.includes(key)?'해제':'장착'}</button></article>`).join('')||'<p class="muted">상점에서 마음에 드는 아이템을 하나씩 모아 보세요.</p>'}</div><p class="pet-store-status" role="status">${esc(petMessage||'')}</p></section><details class="pet-guide"><summary>성장 방법과 돌보기 기록</summary><p>네 가지 돌보기마다 하루 한 번 성장 8과 코인 1을 받아요. 돌보기 코인은 하루 최대 4개입니다. 성장 64 · 192 · 384에서 다음 단계가 열립니다. 하루 2~4가지 돌봄으로 약 12~24일이면 마지막 단계에 도달해요. 인턴 기간은 2027년 2월 26일까지이며, 그 뒤에도 소장품과 성장 기록은 유지돼요. 성장과 보금 코인은 홈페이지 활동 XP와 별도로 쌓여요. 오래 자리를 비워도 상태는 25 아래로 내려가지 않고, 성장 단계는 유지됩니다.</p><ul>${p.history.map(h=>`<li><span>${esc(h.text)}</span><small>${esc(h.time.slice(5,16).replace('T',' '))}</small></li>`).join('')||'<li>첫 돌보기를 해 보세요.</li>'}</ul></details></div>`;updatePetWait();
}
function updatePetWait(){if(location.hash!=='#pet'||!petState)return;const wait=Math.max(0,Math.ceil((petWaitUntil-Date.now())/1000));document.querySelectorAll('[data-pet-care]').forEach(b=>{b.disabled=petBusy||!!petInteraction||wait>0;});const status=document.querySelector('#pet-action-status');if(status&&!petBusy)status.textContent=wait?'잠깐 쉬어요 · '+wait+'초 뒤 다시 돌볼 수 있어요.':'';}
async function changePet(path,data){if(petBusy||petInteraction)return;petBusy=true;try{const result=await petRequest(path,data);petState=result.pet;petMessage=result.message;petLoaded=true;petWaitUntil=Date.now()+Number(result.pet.care_wait||0)*1000;renderPetPage();return true;}catch(error){const status=document.querySelector('#pet-action-status')||document.querySelector('.pet-welcome .pet-notice');if(status)status.textContent=error.message;const nameStatus=document.querySelector('#pet-name-dialog[open] .pet-notice');if(nameStatus)nameStatus.textContent=error.message;const speech=document.querySelector('.pet-speech');if(speech)speech.textContent=error.message;return false;}finally{petBusy=false;updatePetWait();document.querySelectorAll('[data-pet-item]').forEach(b=>{b.disabled=b.dataset.petItemAction==='buy'&&(petState?.owned.includes(b.dataset.petItem)||(!petState?.admin_shop&&petState?.coins<petState?.items[b.dataset.petItem].price));});}}
document.addEventListener('submit',async e=>{const f=e.target;if(!['pet-adopt-form','pet-name-form'].includes(f.id))return;e.preventDefault();const b=f.querySelector('[type=submit],button');b.disabled=true;const ok=await changePet(f.id==='pet-adopt-form'?'/adopt':'/rename',{name:new FormData(f).get('name'),...(f.id==='pet-adopt-form'?{color:new FormData(f).get('color')}: {})});if(ok&&f.id==='pet-name-form')f.closest('dialog').close();else b.disabled=false;});
document.addEventListener('change',e=>{if(e.target.id==='pet-inventory-category'){petInventoryCategory=e.target.value;renderPetPage();}});
document.addEventListener('click',async e=>{const slot=e.target.closest('[data-pet-slot]');if(slot){petWearCategory=slot.dataset.petSlot;renderPetPage();return;}const b=e.target.closest('[data-pet-care],[data-pet-item],.pet-name-edit,#pet-retry,[data-pet-category]');if(!b)return;if(b.dataset.petCategory){petShopCategory=b.dataset.petCategory;renderPetPage();return;}if(b.id==='pet-retry'){loadPet();return;}if(b.dataset.petCare){startPetInteraction(b.dataset.petCare);return;}if(b.dataset.petItem){b.disabled=true;await changePet('/decorate',{item:b.dataset.petItem,action:b.dataset.petItemAction||'toggle'});return;}let modal=document.querySelector('#pet-name-dialog');if(!modal){modal=document.createElement('dialog');modal.id='pet-name-dialog';document.body.append(modal);}modal.innerHTML=`<div class="progress-dialog-head"><h2>이름 변경</h2><button type="button" class="dialog-close-icon" aria-label="닫기">×</button></div><form id="pet-name-form" class="board-form"><label>이름<input class="field" name="name" maxlength="12" value="${esc(petState.name)}" required></label><button type="submit" class="primary">저장</button><p class="pet-notice" role="status"></p></form>`;modal.querySelector('.dialog-close-icon').onclick=()=>modal.close();modal.showModal();});
setInterval(updatePetWait,1000);
setInterval(()=>{if(location.hash==='#pet'&&!document.hidden&&!petBusy&&!document.querySelector('dialog[open]'))loadPet();},60000);

document.addEventListener('change',e=>{if(e.target.matches('#pet-adopt-form input[name=color]')){const art=document.querySelector('.pet-welcome-art');if(art)art.innerHTML=petAvatar(0,'',e.target.value);}});

let petTouch=null,petStrokeBusy=false;
async function strokePet(){
 if(petBusy||petStrokeBusy||petInteraction)return;petStrokeBusy=true;
 const ok=await changePet('/stroke',{});
 if(ok){const target=document.querySelector('.pet-character');target?.classList.add('is-stroked');setTimeout(()=>target?.classList.remove('is-stroked'),1800);}
 petStrokeBusy=false;
}
document.addEventListener('pointerdown',e=>{const target=e.target.closest('.pet-character');if(!target||petInteraction)return;petTouch={id:e.pointerId,x:e.clientX,y:e.clientY,moved:0,target};target.setPointerCapture?.(e.pointerId);});
document.addEventListener('pointermove',e=>{if(!petTouch||e.pointerId!==petTouch.id)return;petTouch.moved+=Math.hypot(e.clientX-petTouch.x,e.clientY-petTouch.y);petTouch.x=e.clientX;petTouch.y=e.clientY;if(petTouch.moved>12)petTouch.target.classList.add('is-stroked');});
document.addEventListener('pointerup',e=>{if(!petTouch||e.pointerId!==petTouch.id)return;petTouch.target.classList.remove('is-stroked');petTouch=null;strokePet();});
document.addEventListener('pointercancel',()=>{petTouch?.target.classList.remove('is-stroked');petTouch=null;});
document.addEventListener('click',e=>{if(e.detail===0&&e.target.closest('.pet-character'))strokePet();});

(function petBlinkLoop(){
 setTimeout(()=>{
  const avatar=document.querySelector('.pet-character .pet-avatar');
  if(avatar&&!document.hidden&&!petTouch&&!petStrokeBusy){avatar.classList.add('is-blinking');setTimeout(()=>avatar.classList.remove('is-blinking'),170);}
  petBlinkLoop();
 },3000+Math.random()*4500);
})();

const petPlayInstructions={clean:'먼지 위를 누른 채 문질러 닦아 주세요. 키보드로는 먼지를 선택하고 Enter를 눌러요.',feed:'밥그릇을 보금이에게 끌어다 주세요. 키보드로는 그릇을 선택하고 Enter를 눌러요.',rest:'달을 4초 동안 누르고 재워 주세요. 키보드는 달에서 Enter로 시작·멈춤할 수 있어요.',study:'책 속 그림과 같은 소품을 골라 주세요. 세 장을 함께 읽어요.'};
function startPetInteraction(action){if(petBusy||petInteraction||Date.now()<petWaitUntil)return;petInteraction={action,done:0,total:action==='clean'?6:action==='rest'?40:3,started:Date.now(),cleaned:[],drag:null,finishing:false};document.querySelector('.pet-room').classList.add('is-playing','play-'+action);document.querySelector('.pet-touch-hint').textContent=petPlayInstructions[action];drawPetInteraction();updatePetWait();}
function drawPetInteraction(){const q=petInteraction,layer=document.querySelector('.pet-play-layer');if(!q||!layer)return;let body='';
 if(q.action==='clean')body=Array.from({length:6},(_,i)=>`<button class="pet-dust ${q.cleaned.includes(i)?'is-gone':''}" data-pet-dust="${i}" style="left:${[15,35,75,87,24,65][i]}%;top:${[65,86,57,82,40,90][i]}%" aria-label="먼지 ${i+1} 닦기"><span></span><span></span><span></span></button>`).join('');
 if(q.action==='feed')body=`<button class="pet-food" aria-label="밥그릇을 보금이에게 주기">${petProp('food')}</button><span class="pet-feed-target" aria-hidden="true">여기로 밥을 주세요 ♡</span>`;
 if(q.action==='rest')body='<button class="pet-moon" aria-label="누르고 있기: 보금이 낮잠">☾</button><span class="pet-sleep-letters">z z Z</span>';
 if(q.action==='study'){const keys=['plant','cat','piggy'];body=`<div class="pet-study-book"><strong>함께 읽기 · ${q.done+1}/3</strong>${petProp(keys[q.done])}<span>같은 그림을 찾아 주세요</span><div>${['cat','piggy','plant'].map(k=>`<button data-pet-answer="${k}" aria-label="${esc(petState.items[k].name)}">${petProp(k)}</button>`).join('')}</div>`;}
 layer.innerHTML=body+`<div class="pet-play-toolbar"><strong>${petActionNames[q.action][1]} · <span id="pet-play-count">${Math.round(q.done/q.total*100)}%</span></strong><progress max="${q.total}" value="${q.done}"></progress><button class="pet-play-cancel" aria-label="돌보기 취소">×</button></div>`;
}
function cancelPetInteraction(){if(!petInteraction||petInteraction.finishing)return;clearInterval(petInteraction.timer);petInteraction=null;renderPetPage();}
async function advancePetInteraction(amount=1){const q=petInteraction;if(!q||q.finishing)return;q.done=Math.min(q.total,q.done+amount);if(q.done<q.total){if(q.action==='rest'){document.querySelector('.pet-play-toolbar progress').value=q.done;document.querySelector('#pet-play-count').textContent=Math.round(q.done/q.total*100)+'%';}else drawPetInteraction();return;}q.finishing=true;clearInterval(q.timer);document.querySelector('.pet-play-toolbar strong').textContent='잘했어요! 보상을 저장하고 있어요…';petInteraction=null;await changePet('/care',{action:q.action});renderPetPage();}
document.addEventListener('click',e=>{const q=petInteraction;if(!q)return;if(e.target.closest('.pet-play-cancel')){cancelPetInteraction();return;}const answer=e.target.closest('[data-pet-answer]');if(answer){if(answer.dataset.petAnswer===['plant','cat','piggy'][q.done])advancePetInteraction();else{answer.classList.add('is-wrong');setTimeout(()=>answer.classList.remove('is-wrong'),400);}return;}if(e.detail===0&&e.target.closest('.pet-moon')){if(q.timer){clearInterval(q.timer);q.timer=null;}else beginPetNap();return;}if(e.detail===0&&e.target.closest('[data-pet-dust],.pet-food')){const dust=e.target.closest('[data-pet-dust]');if(dust)q.cleaned.push(Number(dust.dataset.petDust));advancePetInteraction();}});
document.addEventListener('keydown',e=>{if(e.key==='Escape')cancelPetInteraction();if(petInteraction?.action==='rest'&&e.code==='Space'&&e.target.closest('.pet-moon')){e.preventDefault();beginPetNap();}});
document.addEventListener('keyup',e=>{if(e.code==='Space'&&petInteraction?.action==='rest'){clearInterval(petInteraction.timer);petInteraction.timer=null;}});
function beginPetNap(){const q=petInteraction;if(!q||q.timer)return;document.querySelector('.pet-room').classList.add('is-napping');q.timer=setInterval(()=>advancePetInteraction(),100);}
document.addEventListener('pointerdown',e=>{const q=petInteraction;if(!q||q.finishing)return;if(q.action==='rest'&&e.target.closest('.pet-moon')){e.preventDefault();beginPetNap();return;}if(q.action==='feed'&&e.target.closest('.pet-food')){e.preventDefault();q.drag={id:e.pointerId,food:e.target.closest('.pet-food')};q.drag.food.setPointerCapture(e.pointerId);}if(q.action==='clean'&&e.target.closest('.pet-room')){e.preventDefault();q.drag={id:e.pointerId,x:e.clientX,y:e.clientY,distance:0};}});
document.addEventListener('pointermove',e=>{const q=petInteraction,d=q?.drag;if(!d||d.id!==e.pointerId)return;const room=document.querySelector('.pet-room').getBoundingClientRect();if(q.action==='feed'){d.food.style.left=(e.clientX-room.left)/room.width*100+'%';d.food.style.top=(e.clientY-room.top)/room.height*100+'%';}if(q.action==='clean'){const delta=Math.hypot(e.clientX-d.x,e.clientY-d.y);d.x=e.clientX;d.y=e.clientY;const dust=[...document.querySelectorAll('.pet-dust:not(.is-gone)')].find(b=>{const r=b.getBoundingClientRect();return e.clientX>=r.left&&e.clientX<=r.right&&e.clientY>=r.top&&e.clientY<=r.bottom;});if(dust){d.distance+=delta;dust.style.opacity=Math.max(.2,1-d.distance/70);if(d.distance>60){d.distance=0;q.cleaned.push(Number(dust.dataset.petDust));advancePetInteraction();}}}});
document.addEventListener('pointerup',e=>{const q=petInteraction;if(!q)return;if(q.action==='rest'){clearInterval(q.timer);q.timer=null;}const d=q.drag;if(!d||d.id!==e.pointerId)return;q.drag=null;if(q.action==='feed'){const r=document.querySelector('.pet-character').getBoundingClientRect();if(e.clientX>=r.left&&e.clientX<=r.right&&e.clientY>=r.top&&e.clientY<=r.bottom)advancePetInteraction();else drawPetInteraction();}});
document.addEventListener('pointercancel',()=>{if(petInteraction){clearInterval(petInteraction.timer);petInteraction.timer=null;petInteraction.drag=null;}});
window.addEventListener('hashchange',()=>{if(petInteraction){clearInterval(petInteraction.timer);petInteraction=null;}});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&petInteraction){clearInterval(petInteraction.timer);petInteraction.timer=null;}});
